out=[]
for name,lang,msgs in CL:
    rec={"client":name,"lang":lang,"turns":[]}
    try:
        st,u,dt=call("POST","/users",json={"language":lang,"country":"KZ","src":"qa-test"}); tok=u["token"]; rec["user"]=u["id"]
        st,c,dt=call("POST","/cases",tok,json={"text":"QA-TEST. "+msgs[0],"language":lang,"country":"KZ","accept_terms":True,"defer":True})
        rec["create"]=[st,dt]; cid=c["case"]["id"]; rec["case"]=cid
        for i,m in enumerate(msgs):
            r=chat(tok,cid,("QA-TEST. " if i==0 else "")+m,lang); rec["turns"].append({k:r.get(k) for k in ("status","ttft","total","text","body")})
            time.sleep(2)
        time.sleep(8)
        st,cs,dt=call("GET",f"/cases/{cid}",tok)
        rec["case_view"]={k:cs.get(k) for k in ("status","status_label","stage","scenario","facts","question","actions","proposal","plan","payment","coverage","safety")}
        st,p,dt=call("POST",f"/cases/{cid}/payment",tok,json={"purpose":"document"}); rec["payment_try"]=[st,p if st!=200 else {"payment":p["case"]["payment"]}]
    except Exception as e:
        rec["exception"]=repr(e)[:300]
    out.append(rec); json.dump(out,open("run15.json","w"),ensure_ascii=False,indent=1)
    t=rec["turns"]; print(name, [ (x.get("ttft"),len(x.get("text") or "")) for x in t], (rec.get("case_view") or {}).get("scenario",{}) and rec["case_view"]["scenario"]["id"] if rec.get("case_view",{}).get("scenario") else None, rec.get("payment_try",[None])[0], rec.get("exception",""), flush=True)
